"""Area maps and preparation notes for the deeper dungeon expeditions.

Applied after dungeon definitions, economy, and battle presentation. The driver
owns the active HTML write; this module never rebuilds the older source game.
"""


HELPERS = r'''var depthMapView=`area`,depthMapArea=``;
function depthPlanForUI(state){let current=dungeonPlan(state);if(current)return current;let root={R01:`works`,R02:`tollhouse`,R03:`granary`,R04:`orchard`,R05:`crown`,R06:`heart`}[M(state.area,state.player.x,state.player.y)];return root?dungeonPlan(state,root):null}
function depthExpeditionUI(state){let plan=depthPlanForUI(state);if(!plan)return``;let here=dungeonInfo(state.area,state.player.x,state.player.y),info=plan.info,charges=state.heroes.filter(hero=>hero.maxCharges.some(n=>n>0)),goals=Array.isArray(plan.goals)?plan.goals:[];return`<section class="expedition-plan" data-expedition-plan="${Q(info.root)}"><header><div><span class="eyebrow">${here?`CURRENT EXPEDITION`:`REGIONAL EXPEDITION`}</span><h3>${Q(info.rootName||f[info.root]?.name||info.title)}</h3></div><strong class="depth-floor-label" data-depth-floor="${info.floor}" data-depth-total="${info.total}">${here?`Floor ${info.floor} / ${info.total}`:`${info.total} floors`}</strong></header><p class="expedition-threat">${Q(plan.threat||``)}</p><p>${Q(plan.advice||`Keep enough medicine for the return road. Stairs do not restore HP or spell charges.`)}</p><div class="expedition-columns"><section><h4>Pack before descending</h4><div class="expedition-supplies">${(plan.supplies||[]).map(supply=>{let owned=state.inventory[supply.itemId]??0,recommended=supply.quantity??0;return`<div data-expedition-supply="${Q(supply.itemId)}" data-owned="${owned}" data-recommended="${recommended}" class="${owned<recommended?`supply-low`:``}"><span>${Q(K(supply.itemId)?.name||supply.itemId)}</span><strong>${owned} <small>/ ${recommended} suggested</small></strong></div>`}).join(``)}</div><p class="expedition-hint">Suggested reserves are planning guides, never entry requirements. Keep an inn fund and some medicine for the way back.</p></section><section><h4>Party reserves</h4><div class="expedition-health">${state.heroes.map(hero=>`<span class="${hero.hp===0||hero.status?`reserve-low`:``}">${Q(hero.name)} · ${hero.hp}/${hero.maxHp} HP${hero.status?` · ${Q(hero.status)}`:``}</span>`).join(``)}</div><div class="expedition-charges">${charges.map(hero=>{let remaining=hero.charges.reduce((sum,n)=>sum+n,0),maximum=hero.maxCharges.reduce((sum,n)=>sum+n,0);return`<div data-expedition-charges="${Q(hero.id)}" data-remaining="${remaining}" data-maximum="${maximum}"><strong>${Q(hero.name)} <small>${remaining}/${maximum} charges</small></strong><span>${hero.maxCharges.map((max,tier)=>max?`T${tier+1} ${hero.charges[tier]??0}/${max}`:``).filter(Boolean).join(` · `)}</span></div>`}).join(``)||`<p>No spell charges available. Bring enough supplies for this party.</p>`}</div></section></div><div class="expedition-route"><h4>Route and return</h4><p>${Q(plan.shortcut?.label||`Trace the stairs back to the entrance whenever reserves run low.`)}${plan.shortcut?` <strong>${plan.shortcut.open?`Shortcut open`:``}</strong>`:``}</p>${goals.length?`<ul>${goals.map(goal=>`<li>${Q(typeof goal===`string`?goal:goal.text||goal.label||goal.title||``)}</li>`).join(``)}</ul>`:``}<p class="expedition-hint">Ordinary battles pay less EXP and gold. Train near a safe return, buy for the next threats, then attempt a longer push. Caches are limited; stairs do not refill charges.</p></div></section>`}
function depthLocalMap(state){let current=X.map(),info=dungeonInfo(state.area,state.player.x,state.player.y),colors={g:`#477b55`,d:`#b69e6c`,s:`#8e9965`,f:`#737a81`,b:`#dec890`,w:`#235c9a`,"#":`#25334b`,t:`#285b40`,T:`#27503f`,"^":`#677088`},paths={};current.tiles.forEach((row,y)=>Array.from(row).forEach((tile,x)=>{let color=colors[tile]||`#4f647a`;paths[color]=(paths[color]||``)+`M${x} ${y}h1v1h-1z`}));let landmarks=current.entities.filter(entity=>entity.kind!==`enemy`),symbol=entity=>entity.id.startsWith(`depth-shortcut-`)||entity.id.startsWith(`depth-return-`)?`⇄`:entity.travelKind===`stairs`?entity.stairDirection===`down`?`↓`:`↑`:entity.kind===`exit`?`↗`:entity.kind===`boss`?`◆`:entity.kind===`chest`?`□`:entity.kind===`campfire`?`+`:entity.kind===`rare`?`◇`:`•`,destination=entity=>entity.destination?f[entity.destination]?.name||entity.destination:``;return`<section class="depth-local-map"><p class="map-caption"><strong>${Q(f[state.area].name)}</strong>${info?` · Floor ${info.floor} of ${info.total}`:``}<br>Use the stairs and marked returns on this floor. The map gives directions; it never moves the party.</p><svg class="area-atlas" data-local-map="${Q(state.area)}" viewBox="0 0 ${current.width} ${current.height}" role="img" aria-label="${Q(f[state.area].name)} area map showing the party, stairs and landmarks">${Object.entries(paths).map(([color,path])=>`<path fill="${color}" d="${path}"/>`).join(``)}${landmarks.map(entity=>`<g data-map-stair="${entity.travelKind===`stairs`?Q(entity.id):``}"><title>${Q(entity.name)}${entity.destination?` → ${Q(destination(entity))}`:``}</title><circle cx="${entity.x+.5}" cy="${entity.y+.5}" r=".5" fill="${entity.kind===`boss`?`#e18c79`:entity.kind===`exit`?`#f6d68f`:`#d6ddbc`}" stroke="#10204c" stroke-width=".09"/><text x="${entity.x+.5}" y="${entity.y+.85}" text-anchor="middle" font-family="monospace" font-weight="bold" font-size="1.03" fill="#10204c">${symbol(entity)}</text></g>`).join(``)}<path d="M${state.player.x+.5} ${state.player.y-.12}l.5 1.02-.5-.22-.5.22z" fill="#fff" stroke="#10204c" stroke-width=".13"/></svg><div class="atlas-legend area-legend"><span>▲ Party</span><span>↓ / ↑ Stairs</span><span>⇄ Shortcut</span><span>↗ Exit</span><span>□ Cache</span></div><div class="area-landmarks">${landmarks.map(entity=>`<div data-map-entity="${Q(entity.id)}"><strong><span aria-hidden="true">${symbol(entity)}</span> ${Q(entity.name)}</strong><span>${entity.destination?Q(destination(entity)):`${entity.x}, ${entity.y}`}</span></div>`).join(``)}</div>${info?`<p class="expedition-hint">This is one floor of ${info.total}. Later floors have longer routes and more demanding groups. Find route controls before spending the party's last reserves.</p>`:``}</section>`}
function ut(state){if(depthMapArea!==state.area){depthMapArea=state.area;depthMapView=state.area===`overworld`?`world`:`area`}return`<nav class="map-view-tabs" aria-label="Map view"><button data-map-view="area" aria-pressed="${depthMapView===`area`}" class="${depthMapView===`area`?`active`:``}">Area map</button><button data-map-view="world" aria-pressed="${depthMapView===`world`}" class="${depthMapView===`world`?`active`:``}">World map</button></nav>${depthMapView===`world`?depthWorldMap(state):depthLocalMap(state)}${depthExpeditionUI(state)}`}
'''


CSS = r'''
.map-view-tabs{display:flex;gap:8px;margin:0 0 16px}.map-view-tabs button{background:#142f76;color:#e7efff;border:1px solid #8ba9dc;padding:9px 16px;font:inherit;font-size:12px;cursor:pointer}.map-view-tabs button.active{background:#3456a7;border-color:#fff}.area-atlas{shape-rendering:crispedges;background:#25334b;border:2px solid #9bb4e2;width:100%;max-height:48dvh;display:block}.area-legend{flex-wrap:wrap;gap:7px 15px}.area-landmarks{display:grid;grid-template-columns:1fr 1fr;gap:8px 18px;margin:12px 0}.area-landmarks>div{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid #617bb1;padding:6px 0;font-size:11px;line-height:1.5;min-width:0}.area-landmarks strong{font-weight:normal;min-width:0}.area-landmarks>div>span{color:#c7d9f9;text-align:right}.area-landmarks strong>span{color:#ffe2a3}.expedition-plan{margin-top:22px;padding-top:16px;border-top:1px solid #9bb4e2}.expedition-plan>header{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.expedition-plan h3{margin:5px 0 8px;font-size:17px}.depth-floor-label{white-space:nowrap;color:#ffe2a3;font-weight:normal;font-size:12px;padding-top:5px}.expedition-plan p{font-size:12px;line-height:1.65}.expedition-plan .expedition-threat{color:#ffe2a3}.expedition-columns{display:grid;grid-template-columns:1fr 1fr;gap:24px}.expedition-plan h4{font-size:12px;margin:13px 0 10px;color:#e4ecff}.expedition-supplies>div{display:flex;justify-content:space-between;gap:10px;font-size:11px;line-height:1.6;border-bottom:1px solid #617bb1;padding:7px 0}.expedition-supplies strong{white-space:nowrap;font-weight:normal}.expedition-supplies small{font-size:10px;color:#c7d9f9}.expedition-supplies .supply-low strong,.reserve-low{color:#ffd197}.expedition-health{display:grid;gap:5px;font-size:10px;line-height:1.6}.expedition-charges>div{margin-top:10px;display:grid;gap:4px;font-size:11px}.expedition-charges strong{font-weight:normal}.expedition-charges small{color:#c7d9f9;font-size:10px}.expedition-charges span{font-size:10px;line-height:1.6;color:#c7d9f9}.expedition-plan .expedition-hint{color:#b7cbee;font-size:10px;line-height:1.65}.expedition-route{margin-top:12px;padding-top:1px;border-top:1px solid #617bb1}.expedition-route ul{padding-left:18px;font-size:11px;line-height:1.7}.expedition-route strong{font-size:10px;color:#c2e3ba;font-weight:normal}
@media(max-width:760px){.map-view-tabs button{min-height:38px;padding:8px 13px;font-size:11px}.area-atlas{max-height:none}.area-landmarks{grid-template-columns:1fr;gap:3px}.area-landmarks>div{font-size:10px}.expedition-columns{grid-template-columns:1fr;gap:0}.expedition-plan>header{gap:9px}.expedition-plan h3{font-size:14px}.depth-floor-label{font-size:10px}.expedition-plan p{font-size:11px}.expedition-plan .eyebrow{font-size:9px}.expedition-supplies>div{font-size:11px}.area-legend{font-size:10px}.atlas-modal{max-width:760px}}
'''


def patch(source):
    labels=[]

    def once(old,new,label):
        nonlocal source
        count=source.count(old)
        assert count==1,f'{label}: expected one anchor, found {count}'
        source=source.replace(old,new,1)
        labels.append(label)

    once('function ut(e){','function depthWorldMap(e){','retain canonical exterior world map behind map tabs')
    once('const point=e.area===`overworld`?e.player:k.find(site=>site.area===e.area)??e.overworldReturn;',
         'const point=e.area===`overworld`?e.player:k.find(site=>site.area===(dungeonInfo(e.area)?.root??e.area))??e.overworldReturn;',
         'locate deep dungeon floors at their single exterior world site')
    once('function dt(e){',HELPERS+'function dt(e){','area map and expedition preparation helpers')
    once('+optionalJournal(e)}','+optionalJournal(e)+depthExpeditionUI(e)}','journal shows actual supplies charges and dungeon route guidance')
    once('Vt(`The Roads of Avel`,`WORLD MAP`,ut(e),``,`atlas-modal`)','Vt(`Area & World Map`,`EXPEDITION MAPS`,ut(e),``,`atlas-modal`)','open local and world maps from the existing Map menu')
    once('if(t.dataset.storeFilter){','if(t.dataset.mapView){depthMapView=t.dataset.mapView,Ht();return}if(t.dataset.storeFilter){','map tabs switch views without moving the party')
    once('[`worldmap`,`World Map`]','[`worldmap`,`Area / World Map`]','party menu exposes area and world maps')
    once('title="World map (M)"','title="Area and world map (M)"','map control names both useful views')
    once('open the world map on the road','open the area and world map on the road','update keyboard map help')
    once('Z(`location-name`).textContent=f[e.area].name,Z(`quest-label`).textContent=`QUEST ${Math.min(e.campaign.stage+1,10)} / 10 · ${p(e.area,e.player.x,e.player.y)?`SAFE SHELTER`:n}`',
         'Z(`location-name`).textContent=f[e.area].name,Z(`quest-label`).textContent=`QUEST ${Math.min(e.campaign.stage+1,10)} / 10 · ${p(e.area,e.player.x,e.player.y)?`SAFE SHELTER`:n}${dungeonInfo(e.area,e.player.x,e.player.y)?` · FLOOR ${dungeonInfo(e.area).floor}/${dungeonInfo(e.area).total}`:``}`',
         'keep dungeon floor progress visible during exploration')
    once('</head>','<style>'+CSS+'</style>\n</head>','responsive maps and compact preparation notes')
    return source,labels
